INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('lesson:BASIC-006','lesson','Podzespoły / Components','Zasilacz i wejście zasilania','Power adapter and input','steps: Sprawdź gniazdko, kabel i oznaczenia zasilacza.; Porównaj napięcie i wymaganą moc ze specyfikacją.; Nie używaj przewodu z uszkodzoną izolacją.; Przy iskrzeniu, nadpaleniu lub luźnym gnieździe przerwij próby. body: Jak to działa: Zasilacz dostarcza energię. Zgodność wtyku, parametrów i — przy USB‑C — obsługi właściwego profilu zasilania jest niezbędna. Typowe objawy: Brak reakcji, przerywane ładowanie lub wyłączanie pod obciążeniem mogą wynikać z kabla, gniazda albo elektroniki. Pierwszy bezpieczny test: Sprawdź gniazdko, stan przewodu, oznaczenia zgodności i kontrolki. Nie używaj uszkodzonego kabla. Budowa od środka: Zewnętrzna ładowarka lub zasilacz PC współpracuje z przewodem i wejściem komputera. Wewnątrz zasilacza mogą utrzymywać się niebezpieczne napięcia. Przed wymianą: Dobierz urządzenie według specyfikacji producenta: napięcia, wymaganej mocy i właściwego złącza. Samo dopasowanie wtyku nie wystarcza. Częsty błąd: Zakładanie, że każdy kabel i zasilacz USB‑C zapewnia te same funkcje, lub otwieranie obudowy zasilacza. Kiedy do serwisu: Przy nadpaleniu, iskrzeniu, luźnym gnieździe albo podejrzeniu uszkodzenia wewnętrznego toru zasilania. warning: Nie otwieraj zasilacza sieciowego — wewnątrz mogą występować niebezpieczne napięcia.','stepsEn: Check the wall outlet, cable and adapter label.; Compare voltage and required power with the device specification.; Do not use a cable with damaged insulation.; Stop testing if there is sparking, burning or a loose jack. bodyEn: How it works: The adapter supplies power to the computer. Connector type, electrical ratings and—on USB-C—the supported power-delivery profile must all match. Typical symptoms: No response, intermittent charging or shutdowns under load can be caused by the cable, jack or internal electronics. First safe test: Check the wall outlet, cable condition, adapter labels and status indicators. Do not use a damaged cable. Internal design: An external charger or PC power supply works with a cable and the computer power input. Dangerous voltages may remain inside a power supply. Before replacement: Choose an adapter using the manufacturer specifications: voltage, required power and correct connector. A matching plug alone is not enough. Common mistake: Assuming all USB-C cables and adapters provide the same features, or opening a mains power adapter. When to refer to a service technician: Stop and refer the device if there is burning, sparking, a loose jack or a suspected internal power-path fault. warningEn: Do not open a mains power adapter; hazardous voltages may remain inside.','podstawy, komponenty, diagnoza, serwis, zasilacz i wejście zasilania',''),
('lesson:BASIC-007','lesson','Podzespoły / Components','Bateria i ładowanie','Battery and charging','steps: Sprawdź zgodność ładowarki i ustawiony limit ładowania.; W Windows wygeneruj raport: powercfg /batteryreport.; Sprawdź numer części baterii przed wymianą.; Oceń obudowę pod kątem puchnięcia i uszkodzeń. body: Jak to działa: Bateria magazynuje energię, a elektronika urządzenia zarządza jej ładowaniem i użytkowaniem. Typowe objawy: Krótki czas pracy i brak ładowania mogą wynikać z baterii, ustawionego limitu ładowania lub zasilacza. Pierwszy bezpieczny test: Sprawdź ustawienia i zgodność ładowarki. W Windows raport stanu baterii można utworzyć poleceniem powercfg /batteryreport. Budowa od środka: Pakiet obejmuje ogniwa, elektronikę ochronną i złącze. Jego kształt oraz sposób montażu zależą od modelu laptopa. Przed wymianą: Sprawdź numer części, zgodność elektryczną i mechaniczną oraz instrukcję serwisową. Nie używaj pakietu o niepewnym pochodzeniu. Częsty błąd: Ignorowanie limitu ładowania w ustawieniach lub wielokrotne podłączanie spuchniętej baterii „dla sprawdzenia”. Kiedy do serwisu: Przy spuchnięciu, uszkodzeniu mechanicznym, zapachu, silnym nagrzewaniu lub trudno dostępnej baterii wewnętrznej. Nie ładuj uszkodzonego pakietu. warning: Spuchniętej, uszkodzonej lub przegrzewającej się baterii nie ładuj ani nie używaj.','stepsEn: Check charger compatibility and any configured charge limit.; In Windows, generate a report with: powercfg /batteryreport.; Verify the battery part number before replacement.; Inspect the pack for swelling or physical damage. bodyEn: How it works: The battery stores energy, while protection and charging electronics manage charging and use. Typical symptoms: Short runtime and charging failures may be caused by the battery, a configured charge limit or the adapter. First safe test: Check charging settings and adapter compatibility. In Windows, create a battery report by running powercfg /batteryreport. Internal design: A battery pack contains cells, protection electronics and a connector. Its shape and mounting method depend on the laptop model. Before replacement: Verify the part number, electrical and mechanical compatibility, and the service procedure. Avoid packs from unknown sources. Common mistake: Ignoring a configured charge limit or repeatedly connecting a swollen battery just to see whether it works. When to refer to a service technician: Refer a swollen, physically damaged, hot or difficult-to-remove battery. Do not charge a damaged pack. warningEn: Do not charge or use a swollen, damaged or overheating battery.','podstawy, komponenty, diagnoza, serwis, bateria i ładowanie',''),
('lesson:BASIC-008','lesson','Podzespoły / Components','Wentylator, radiator i temperatura','Fan, heatsink and temperature','steps: Zapisz temperatury, taktowania i obroty wentylatora.; Sprawdź drożność wlotów i wylotów powietrza.; Oczyść radiator bez uszkadzania łopatek.; Dobierz pastę i termopady zgodnie z konstrukcją. body: Jak to działa: Radiator odbiera ciepło, a wentylator przepycha powietrze. Materiał termiczny wspomaga kontakt między powierzchniami. Typowe objawy: Hałas, spadek wydajności i wyłączenia mogą wskazywać na niedrożny wylot lub niesprawne chłodzenie. Pierwszy bezpieczny test: Odsłoń wloty powietrza, sprawdź obciążenie systemu i temperatury. Przy nagłym wyłączaniu przerwij testy. Budowa od środka: Zestaw może składać się z wentylatora, rurek cieplnych, radiatora oraz pasty lub termopadów o określonej grubości. Przed wymianą: Dobierz część do numeru modelu i rozmieszczenia mocowań. Nie zastępuj termopadów przypadkową grubością. Częsty błąd: Zakładanie, że sama wymiana pasty naprawi wentylator, albo blokowanie wirnika podczas pracy. Kiedy do serwisu: Gdy wentylator ociera, laptop regularnie gaśnie lub demontaż układu wymaga rozebrania znacznej części urządzenia. warning: Nie zastępuj termopadów pastą bez potwierdzenia wymaganej grubości i parametrów.','stepsEn: Record temperatures, clock speeds and fan RPM.; Check that air intakes and exhausts are clear.; Clean the heatsink without damaging fan blades.; Choose thermal paste and pads according to the design. bodyEn: How it works: The heatsink absorbs heat and the fan moves air. Thermal material improves contact between cooling surfaces. Typical symptoms: Noise, reduced performance and shutdowns may indicate a blocked exhaust, failed fan or poor heatsink contact. First safe test: Check that air vents are clear, review system load and monitor temperatures. Stop stress testing if the device shuts down unexpectedly. Internal design: A cooling assembly may include a fan, heat pipes, heatsink, thermal paste and pads of specified thickness. Before replacement: Match replacement parts to the exact model and mounting points. Do not substitute thermal pads with arbitrary thickness. Common mistake: Assuming that replacing thermal paste will repair a failed fan, or blocking the fan blades while it is running. When to refer to a service technician: Refer the device if the fan rubs, the laptop repeatedly shuts down, or disassembly requires extensive teardown. warningEn: Do not replace thermal pads with paste without confirming the required thickness and specifications.','podstawy, komponenty, diagnoza, serwis, wentylator, radiator i temperatura',''),
('lesson:BASIC-009','lesson','Podzespoły / Components','Porty USB, HDMI i złącza','USB, HDMI and connectors','steps: Sprawdź drugi, znany jako sprawny kabel i urządzenie.; Obejrzyj port bez wkładania metalowych narzędzi.; Sprawdź, czy port obsługuje wymaganą funkcję.; Ustal, czy gniazdo jest na osobnej płytce czy na płycie głównej. body: Jak to działa: Porty przenoszą dane, obraz lub zasilanie. Podobne złącza USB‑C mogą obsługiwać różne funkcje. Typowe objawy: Przerywane połączenie może wynikać z kabla, ustawień, urządzenia albo mechanicznego uszkodzenia gniazda. Pierwszy bezpieczny test: Porównaj sprawny kabel i drugie urządzenie. Sprawdź specyfikację portu i obejrzyj złącze bez używania metalowych narzędzi. Budowa od środka: Gniazdo ma styki oraz mocowanie do obudowy lub płytki. Sygnały przechodzą przez kontrolery i obwody zabezpieczające. Przed wymianą: Sprawdź dokładny typ i układ pinów oraz czy port jest częścią osobnej płytki, czy płyty głównej. Częsty błąd: Przypisywanie brakującego obrazu z USB‑C awarii, mimo że dany port nie obsługuje wyjścia wideo. Kiedy do serwisu: Przy luźnym, nadpalonym lub wyrwanym gnieździe. Przestań go używać, szczególnie jeśli służy do ładowania. warning: Przestań używać portu, który jest nadpalony, luźny lub mechanicznie wyrwany.','stepsEn: Test with a known-good cable and device.; Inspect the port without inserting metal tools.; Check whether the port supports the required feature.; Determine whether the connector is on a separate daughterboard or the mainboard. bodyEn: How it works: Ports carry data, video or power. USB-C connectors that look identical may support different functions. Typical symptoms: An intermittent connection may be caused by the cable, connected device, settings or mechanical damage to the port. First safe test: Compare a known-good cable and device. Check the port specification and inspect the connector without using metal tools. Internal design: A connector has contacts and mechanical anchors to the case or a circuit board. Signals pass through controllers and protection circuits. Before replacement: Check the exact connector type and pin layout, and determine whether the port is on a separate daughterboard or the mainboard. Common mistake: Blaming a USB-C port for missing video when that particular port does not support video output. When to refer to a service technician: Refer a loose, burnt or detached connector. Stop using it, especially if it is also used for charging. warningEn: Stop using a port that is burnt, loose or mechanically detached.','podstawy, komponenty, diagnoza, serwis, porty usb, hdmi i złącza',''),
('lesson:BASIC-010','lesson','Podzespoły / Components','Klawiatura i touchpad','Keyboard and touchpad','steps: Sprawdź ustawienia i działanie urządzenia zewnętrznego.; Ustal, czy problem dotyczy pojedynczych klawiszy czy całego modułu.; Odłącz baterię przed kontrolą taśm.; Potwierdź układ klawiszy i sposób mocowania części zamiennej. body: Jak to działa: Klawiatura i touchpad przekazują polecenia przez kontrolery i połączenia z płytą. Touchpad może mieć osobny przełącznik. Typowe objawy: Pojedynczy niedziałający klawisz, brak reakcji całej klawiatury i awaria touchpada wymagają różnych sprawdzeń. Pierwszy bezpieczny test: Sprawdź ustawienia i urządzenie zewnętrzne. Po zalaniu wyłącz sprzęt i nie uruchamiaj go ponownie. Budowa od środka: Pod klawiszami znajdują się mechanizmy i warstwy przewodzące. Touchpad ma powierzchnię czujnika oraz taśmę połączeniową. Przed wymianą: Potwierdź model, układ klawiszy, typ podświetlenia i sposób mocowania; w niektórych laptopach klawiatura stanowi część obudowy. Częsty błąd: Odrywanie klawiszy lub dalsze testowanie laptopa po zalaniu, zanim zostanie bezpiecznie oceniony. Kiedy do serwisu: Po kontakcie z cieczą, przy uszkodzonej taśmie lub gdy wymiana wymaga demontażu wielu elementów obudowy. warning: Po zalaniu wyłącz sprzęt, odłącz zasilanie i nie uruchamiaj go ponownie do czasu oceny.','stepsEn: Check settings and test an external input device.; Determine whether the issue affects individual keys or the whole module.; Disconnect the battery before inspecting ribbon cables.; Verify keyboard layout and replacement mounting method. bodyEn: How it works: The keyboard and touchpad send input through controllers and board connections. A touchpad may also have a separate switch. Typical symptoms: A single dead key, a completely unresponsive keyboard and a touchpad failure require different checks. First safe test: Check operating-system settings and test an external input device. After a spill, shut the device down and do not restart it. Internal design: Keys use mechanical and conductive layers. A touchpad has a sensor surface and a ribbon-cable connection. Before replacement: Confirm the model, keyboard layout, backlight type and mounting method. Some laptops integrate the keyboard into the top case. Common mistake: Removing keycaps unnecessarily or continuing to test a laptop after liquid exposure before it has been safely inspected. When to refer to a service technician: Refer the device after liquid exposure, with a damaged ribbon cable, or when replacement requires extensive case disassembly. warningEn: After a spill, power the device off, disconnect power and do not restart it before inspection.','podstawy, komponenty, diagnoza, serwis, klawiatura i touchpad',''),
('lesson:BASIC-011','lesson','Podzespoły / Components','Wi-Fi i sieć','Wi-Fi and networking','steps: Sprawdź tę samą sieć na innym urządzeniu.; Wyłącz tryb samolotowy i sprawdź ustawienia karty.; Porównaj Wi-Fi z połączeniem przewodowym.; Przed wymianą sprawdź format modułu i anteny. body: Jak to działa: Karta łączy komputer z routerem przez anteny. Dostęp do internetu zależy również od działania samej sieci. Typowe objawy: Brak sieci, słaby sygnał lub połączenie bez internetu mogą wynikać z routera, ustawień lub sterownika. Pierwszy bezpieczny test: Sprawdź sieć na drugim urządzeniu i wyłącz tryb samolotowy. Jeśli możesz, porównaj połączenie przewodowe. Budowa od środka: Moduł radiowy współpracuje z antenami, często umieszczonymi w pokrywie laptopa. Bluetooth może korzystać z tego samego modułu. Przed wymianą: Potwierdź format modułu, zgodność platformy i liczbę złączy antenowych. Nie ciągnij anten za przewody. Częsty błąd: Wymiana karty, gdy problem występuje także na telefonie połączonym z tym samym routerem. Kiedy do serwisu: Gdy złącza antenowe są urwane, moduł jest wlutowany albo uszkodzona jest antena w pokrywie. warning: Nie wymieniaj karty, zanim nie wykluczysz problemu routera lub całej sieci.','stepsEn: Test the same network on another device.; Disable airplane mode and check adapter settings.; Compare Wi-Fi with a wired connection.; Before replacement, verify the module form factor and antennas. bodyEn: How it works: The wireless card connects to the router through antennas. Bluetooth may use the same wireless module. Typical symptoms: No network, weak signal or a connection without internet access can be caused by the router, settings or driver. First safe test: Test the same network on another device and disable airplane mode. Compare with a wired connection when possible. Internal design: The radio module works with antennas, often routed into the laptop display lid. Bluetooth may share the module. Before replacement: Confirm the module form factor, platform compatibility and number of antenna connectors. Never pull antennas by their wires. Common mistake: Replacing the wireless card when the same network problem also affects a phone connected to that router. When to refer to a service technician: Refer the device if antenna connectors are torn off, the module is soldered or an antenna in the display lid is damaged. warningEn: Do not replace the adapter before ruling out a router or network-wide problem.','podstawy, komponenty, diagnoza, serwis, wi-fi i sieć',''),
('lesson:BASIC-012','lesson','Podzespoły / Components','Dźwięk, głośniki i mikrofon','Audio, speakers and microphone','steps: Sprawdź wybrane urządzenie wyjściowe i poziom głośności.; Sprawdź uprawnienia mikrofonu.; Porównaj głośniki ze słuchawkami.; Sprawdź przewody i złącza po odłączeniu zasilania. body: Jak to działa: System wybiera wejście i wyjście dźwięku: głośniki, słuchawki, HDMI lub Bluetooth. Typowe objawy: Cisza, trzaski lub niedziałający mikrofon mogą wynikać z ustawień, sterownika, przewodu lub gniazda. Pierwszy bezpieczny test: Sprawdź wybrane urządzenie, głośność i uprawnienia mikrofonu. Porównaj wbudowane głośniki ze słuchawkami. Budowa od środka: Tor audio obejmuje kontroler, wzmacniacz, głośniki, mikrofon oraz ewentualne gniazdo słuchawkowe. Przed wymianą: Sprawdź numer części, położenie głośnika i typ przewodu. Najpierw wyklucz błędnie wybrane wyjście dźwięku. Częsty błąd: Wymiana głośników, kiedy system przesyła dźwięk do monitora HDMI albo urządzenia Bluetooth. Kiedy do serwisu: Przy uszkodzonym gnieździe, śladach cieczy albo braku dźwięku na wielu sprawnych urządzeniach po wykluczeniu ustawień. warning: Nie wymieniaj głośników, zanim nie wykluczysz błędnie wybranego wyjścia audio.','stepsEn: Check the selected output device and volume level.; Check microphone permissions.; Compare built-in speakers with headphones.; Inspect cables and connectors with power disconnected. bodyEn: How it works: The operating system selects an audio input and output: speakers, headphones, HDMI or Bluetooth. Typical symptoms: Silence, crackling or a non-working microphone may be caused by settings, drivers, cables or a connector. First safe test: Check the selected device, volume and microphone permissions. Compare the built-in speakers with headphones. Internal design: The audio path includes a controller, amplifier, speakers, microphone and sometimes a headphone jack. Before replacement: Check the part number, speaker location and cable type. First rule out an incorrectly selected audio output. Common mistake: Replacing speakers when the system is sending audio to an HDMI display or Bluetooth device. When to refer to a service technician: Refer the device if a jack is damaged, liquid exposure is present, or audio fails across multiple known-good devices after settings are ruled out. warningEn: Do not replace speakers before ruling out an incorrectly selected audio output.','podstawy, komponenty, diagnoza, serwis, dźwięk, głośniki i mikrofon',''),
('lesson:LATEST-001','lesson','Windows / aktualizacje','Windows 11 26H2 — diagnostyka wydania i aktualizacji','Windows 11 26H2 — diagnostyka wydania i aktualizacji','steps: Uruchom winver i zapisz wydanie, kompilację oraz edycję systemu.; Zapisz historię aktualizacji i numer KB, po którym wystąpił objaw.; Sprawdź stronę Windows release health dla dokładnej wersji i znanych problemów.; Porównaj datę awarii z instalacją sterownika, firmware lub aktualizacji.; W razie potrzeby przetestuj rozwiązanie na kopii lub urządzeniu testowym, a nie na jedynym komputerze klienta.; Po zmianie uruchom test pierwotnego objawu i zapisz wynik. body: Windows 11 26H2 jest aktualnym wydaniem dostępnym dla kwalifikujących się urządzeń. Wspólna baza serwisowa 24H2/25H2/26H2 oznacza, że przed diagnozą trzeba ustalić dokładną wersję, kompilację i ostatni pakiet KB. Nie instaluj losowo opcjonalnych wydań Preview na komputerze klienta. warning: Nie odinstalowuj zbiorczo aktualizacji bezpieczeństwa. Wydania Preview są opcjonalne; zawsze oceniaj znane problemy i możliwość wycofania. source: Windows 11 26H2 · Release Health','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','win11,26H2,KB5127936,Windows Update','Windows 11 26H2 · Release Health'),
('lesson:LATEST-002','lesson','Windows / bezpieczeństwo','Secure Boot 2026 — wymiana certyfikatów 2011 na 2023','Secure Boot 2026 — wymiana certyfikatów 2011 na 2023','steps: Zapisz producenta, model, wersję UEFI i stan Secure Boot.; Sprawdź status certyfikatów według oficjalnej procedury Microsoft, w tym zdarzenia systemowe.; Przed zmianą firmware potwierdź dostępność klucza odzyskiwania BitLocker u właściciela.; Sprawdź aktualizacje BIOS/UEFI OEM i znane ostrzeżenia dla modelu.; Przetestuj aktualizację najpierw na zgodnym urządzeniu testowym.; Po wdrożeniu zweryfikuj status certyfikatów, zimny start i brak nieoczekiwanych monitów BitLocker. body: Certyfikaty Secure Boot wydane w 2011 roku zaczęły wygasać w czerwcu 2026. Samo wygaśnięcie nie musi zatrzymać uruchamiania Windows, ale może ograniczyć przyszłe zabezpieczenia wczesnego rozruchu. Diagnoza musi uwzględniać UEFI, firmware OEM i stan BitLocker. warning: Nie wyłączaj Secure Boot jako obejścia. Nie czyść TPM i nie zmieniaj kluczy PK/KEK/db bez procedury OEM i planu odzyskiwania. source: Secure Boot certificates 2026','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','Secure Boot,UEFI,2026,certyfikaty,boot','Secure Boot certificates 2026'),
('lesson:LATEST-003','lesson','Dyski / szyfrowanie','BitLocker po aktualizacji BIOS/UEFI i TPM','BitLocker po aktualizacji BIOS/UEFI i TPM','steps: Zapisz komunikat i identyfikator klucza odzyskiwania — nie zapisuj samego klucza w publicznym raporcie.; Ustal, czy problem zaczął się po zmianie BIOS, TPM, Secure Boot lub aktualizacji Windows.; Sprawdź stan TPM, WinRE, tryb UEFI i partycję systemową zgodnie z dokumentacją Microsoft.; Nie używaj opcji Clear TPM jako pierwszego kroku.; Przy legalnym dostępie właściciela użyj właściwego klucza odzyskiwania i sprawdź, czy system startuje.; Po naprawie przywróć uzgodnioną ochronę i zweryfikuj stan szyfrowania. body: Zmiana firmware, ustawień Secure Boot lub konfiguracji TPM może spowodować żądanie klucza odzyskiwania. Przyjęcie klucza odzyskiwania nie oznacza awarii SSD. Zanim zmienisz firmware, wykonaj kopię danych i potwierdź, że właściciel ma właściwy klucz. warning: Wyczyszczenie TPM może spowodować utratę dostępu do kluczy i danych. Nigdy nie proś klienta o wysłanie klucza BitLocker na czat. source: BitLocker troubleshooting','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','BitLocker,TPM,BIOS,Recovery Key','BitLocker troubleshooting'),
('lesson:LATEST-004','lesson','Windows / audio','Windows 11 26H2 — USB Audio Class 1.0 i Code 10','Windows 11 26H2 — USB Audio Class 1.0 i Code 10','steps: Zapisz dokładny model urządzenia audio i identyfikator sprzętu USB.; Sprawdź, czy urządzenie rzeczywiście używa USB Audio Class 1.0.; Zapisz wersję Windows, kompilację i KB z historii aktualizacji.; Przetestuj urządzenie na innym porcie bez huba oraz na drugim komputerze.; Sprawdź bieżący status problemu w Windows release health i dostępne poprawki.; Zapisz, czy działa stereo, inny tryb kanałów i sterownik OEM. body: Microsoft dokumentuje problem części urządzeń USB Audio Class 1.0, które po wybranych aktualizacjach mogą zgłaszać Code 10, brak dźwięku lub niedostępne ustawienia. Nie dotyczy to automatycznie wszystkich kart dźwiękowych USB. warning: Nie usuwaj wszystkich sterowników audio i nie instaluj przypadkowych pakietów. Status problemu może się zmieniać wraz z aktualizacjami Microsoft. source: Windows 11 26H2 known issues','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','USB Audio,Code 10,26H2,dźwięk','Windows 11 26H2 known issues'),
('lesson:LATEST-005','lesson','Windows / grafika i audio','Windows 11 26H2 — HDMI/DisplayPort audio na GPU AMD','Windows 11 26H2 — HDMI/DisplayPort audio na GPU AMD','steps: Sprawdź, czy monitor lub amplituner ma głośniki i czy jest wybrany jako urządzenie wyjściowe.; Zapisz model GPU, wersję sterownika Radeon i numer kompilacji Windows.; Przetestuj inny kabel/port i sprawdź urządzenie HDMI/DisplayPort w Menedżerze urządzeń.; Sprawdź notatki wydania KB5127936 i późniejszych aktualizacji.; Jeśli aktualizacja ma zastosowanie, zainstaluj ją przez wspierany kanał po kopii i zgodzie klienta.; Potwierdź dźwięk po restarcie, zmianie wejścia monitora i ponownym podłączeniu. body: Aktualizacja KB5127936 z 28 października 2026 wymienia poprawkę dotyczącą odtwarzania dźwięku HDMI i DisplayPort na niektórych kartach AMD. Przy diagnozie trzeba oddzielić błąd sterownika audio, wybór wyjścia i problem aktualizacji Windows. warning: Nie pobieraj sterownika z serwisów agregujących. W laptopie sprawdź również pakiet OEM, jeśli producent dostarcza dostosowany sterownik. source: KB5127936 Windows 11','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','AMD,Radeon,HDMI,DisplayPort,audio,KB5127936','KB5127936 Windows 11'),
('lesson:LATEST-006','lesson','Porty / USB4 i dokowanie','Windows 11 26H2 — stacja dokująca USB4 i wybudzanie','Windows 11 26H2 — stacja dokująca USB4 i wybudzanie','steps: Odczytaj specyfikację portu komputera i stacji dokującej.; Zapisz firmware docka, wersję BIOS i sterowników chipsetu/GPU.; Przetestuj monitor bezpośrednio w laptopie, a następnie przez dock.; Powtórz cykl uśpienia/wybudzenia przy podłączonym jednym monitorze.; Dodawaj kolejne urządzenia i monitory pojedynczo, aby znaleźć konflikt.; Sprawdź znane poprawki Windows i firmware producenta stacji. body: Windows 11 26H2 zawiera usprawnienia niezawodności wyświetlaczy podłączonych przez stacje i huby USB4, szczególnie przy powrocie ze stanu wstrzymania. Nie oznacza to, że każdy port USB-C obsługuje USB4. warning: Nie zakładaj, że złącze USB-C automatycznie przenosi obraz, ładowanie i USB4. Weryfikuj funkcje oraz moc w specyfikacji modelu. source: Windows 11 26H2 features','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','USB4,dock,standby,wybudzanie,display','Windows 11 26H2 features'),
('lesson:LATEST-007','lesson','Sieć / Bluetooth','Bluetooth LE Audio — diagnostyka mikrofonu i ponownego połączenia','Bluetooth LE Audio — diagnostyka mikrofonu i ponownego połączenia','steps: Zapisz model adaptera, słuchawek i wersje firmware.; Usuń stare parowanie po zapisaniu konfiguracji, a następnie przeprowadź ponowne parowanie.; Sprawdź profil audio, wybrane wejście/wyjście i uprawnienia mikrofonu.; Porównaj połączenie w stanie aktywnym i po hibernacji.; Zaktualizuj sterownik Bluetooth ze strony OEM/Intel zgodnie z modelem.; Wykonaj próbę rozmowy, mikrofonu, multimediów i ponownego połączenia. body: Bluetooth LE Audio opiera się na funkcjach sprzętu, kontrolera, sterownika, systemu i słuchawek. Windows 11 26H2 wymienia poprawę niezawodności LE Audio, połączeń głosowych i ponownego łączenia po hibernacji. warning: Nie myl LE Audio z klasycznym Bluetooth audio. Obsługa zależy od zgodności komputera i akcesorium. source: Windows 11 26H2 features','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','Bluetooth,LE Audio,Windows 11,sterownik','Windows 11 26H2 features'),
('lesson:LATEST-008','lesson','Nowe platformy / NPU i AI','NPU w komputerze AI — diagnostyka sterownika i użycia','NPU w komputerze AI — diagnostyka sterownika i użycia','steps: Ustal dokładny model procesora/platformy i czy komputer ma NPU.; Sprawdź Menedżer zadań → Wydajność, czy widoczny jest NPU.; Zapisz wersję sterownika NPU/chipsetu i firmware OEM.; Przetestuj funkcję AI obsługiwaną przez producenta, nie losowy benchmark.; Porównaj obciążenie CPU/GPU/NPU i pobór energii podczas tego samego zadania.; Po aktualizacji sterownika sprawdź aplikację, hibernację i wybudzanie. body: NPU to wyspecjalizowany procesor do operacji AI. Windows może pokazywać użycie NPU w Menedżerze zadań, ale tylko gdy platforma, sterowniki i aplikacja obsługują tę funkcję. Nie każdy komputer z logo AI ma identyczne możliwości. warning: Wymagania funkcji Copilot+ nie są uniwersalnym wymogiem dla każdego NPU. Nie instaluj pakietów AI spoza strony OEM. source: Microsoft NPU devices guide','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','NPU,AI PC,Copilot+,Windows ML,sterowniki','Microsoft NPU devices guide'),
('lesson:LATEST-009','lesson','Nowe platformy / NPU i AI','Copilot+ PC — sprawdzanie wymagań NPU i funkcji AI','Copilot+ PC — sprawdzanie wymagań NPU i funkcji AI','steps: Zidentyfikuj model CPU/NPU w dokumentacji OEM.; Sprawdź czy NPU spełnia wymagania danej funkcji, a nie tylko ogólną klasę AI PC.; Ustal architekturę x64/Arm i dostępne sterowniki.; Sprawdź wersję Windows oraz aktualizacje komponentów AI.; Uruchom tylko funkcję wspieraną na tym konkretnym urządzeniu.; Zapisz wynik, użycie NPU i zachowanie baterii/temperatur. body: Dokumentacja Microsoft opisuje wymaganie NPU o wydajności 40+ TOPS dla wielu funkcji Copilot+ PC. Weryfikuj konkretny model, obsługę systemu i listę dostępnych funkcji, zamiast opierać się wyłącznie na nazwie handlowej. warning: 40 TOPS nie gwarantuje zgodności każdej aplikacji ani funkcji AI. Wymagania sprawdzaj osobno dla każdej funkcji. source: Microsoft Copilot+ PC guide','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','Copilot+,NPU,TOPS,AI PC','Microsoft Copilot+ PC guide'),
('lesson:LATEST-010','lesson','Pamięć / DDR5 i CUDIMM','Intel Core Ultra 200S Plus i zgodność 4-Rank CUDIMM','Intel Core Ultra 200S Plus i zgodność 4-Rank CUDIMM','steps: Zapisz dokładny model CPU, płyty, rewizję i wersję BIOS.; Sprawdź listę zgodności pamięci producenta płyty (QVL).; Zweryfikuj, czy dana płyta obsługuje konkretny typ i pojemność 4-Rank CUDIMM.; Zamontuj pamięć po odłączeniu zasilania i postępuj według instrukcji płyty.; Po pierwszym starcie pozwól zakończyć trening pamięci; nie przerywaj cyklu bez potrzeby.; Testuj stabilność przy ustawieniach JEDEC, dopiero potem sprawdzaj profil producenta. body: Intel ogłosił w marcu 2026 serię Core Ultra 200S Plus i wczesną obsługę modułów 4-Rank CUDIMM do 128 GB na moduł, ale tylko na wybranych płytach i konfiguracjach. Zgodność wymaga weryfikacji CPU, chipsetu, BIOS oraz listy pamięci. warning: Nie zakładaj, że 4-Rank CUDIMM działa na każdej płycie LGA1851/Intel 800. Nie obiecuj zgodności bez QVL i wersji BIOS. source: Intel Core Ultra 200S Plus announcement','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','Intel,Core Ultra 200S Plus,CUDIMM,DDR5','Intel Core Ultra 200S Plus announcement'),
('lesson:LATEST-011','lesson','Procesor / platforma AMD','AMD Ryzen 9000 — BIOS, chipset i sterowniki OEM','AMD Ryzen 9000 — BIOS, chipset i sterowniki OEM','steps: Zapisz CPU, płytę, chipset, wersję BIOS i model grafiki.; Sprawdź listę obsługiwanych CPU i minimalną wersję BIOS na stronie płyty.; Zapisz wersję pakietu chipsetu i sterownika grafiki.; W laptopie porównaj sterownik AMD z pakietem OEM.; Zaktualizuj tylko komponent, którego dotyczy objaw, według oficjalnych instrukcji.; Powtórz test stabilności, uśpienia, dźwięku, grafiki i urządzeń. body: W platformach AMD Ryzen 9000 ważna jest zgodność BIOS, chipsetu, pamięci i sterowników. AMD przypomina, że w laptopach i komputerach AIO sterowniki OEM mogą być dostosowane do funkcji danego systemu. warning: Nie wymuszaj sterownika desktopowego na laptopie, jeżeli OEM wymaga pakietu dostosowanego. Nie aktualizuj BIOS bez kopii i klucza BitLocker. source: AMD Ryzen 9000 downloads','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','AMD,Ryzen 9000,chipset,BIOS,Adrenalin','AMD Ryzen 9000 downloads'),
('lesson:LATEST-012','lesson','Grafika / NVIDIA RTX','NVIDIA Blackwell RTX 50 — sterownik, DLSS i test GPU','NVIDIA Blackwell RTX 50 — sterownik, DLSS i test GPU','steps: Zapisz dokładny model GPU, VBIOS, sterownik i wersję aplikacji.; Zbierz temperaturę rdzenia, hotspot, pamięć i pobór mocy w spoczynku.; Wykonaj bazowy test bez Frame Generation i bez zmiany ustawień OC.; Sprawdź artefakty, błędy sterownika, reset TDR i zdarzenia systemowe.; Następnie testuj DLSS/Frame Generation jako funkcję osobną, w obsługiwanej grze.; Porównaj wyniki po czystej instalacji sterownika pobranego z NVIDIA. body: Karty RTX 50 wykorzystują architekturę Blackwell i nowe generacje rdzeni Tensor/RT. DLSS Multi Frame Generation i inne techniki AI wpływają na obraz i FPS; przy serwisie trzeba mierzyć zarówno stabilność renderowania, jak i rzeczywiste opóźnienie oraz artefakty. warning: Nie używaj generowanych klatek jako jedynego miernika sprawności GPU. Testuj podstawowe renderowanie, temperatury, pamięć i stabilność niezależnie. source: NVIDIA GeForce RTX 50','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','NVIDIA,RTX 50,Blackwell,DLSS,driver,GPU','NVIDIA GeForce RTX 50'),
('lesson:LATEST-013','lesson','Dyski / NVMe PCIe 5.0','PCIe 5.0 NVMe — temperatura, radiator i throttling','PCIe 5.0 NVMe — temperatura, radiator i throttling','steps: Zapisz model SSD, interfejs PCIe, firmware i pojemność.; Odczytaj temperatury i kondycję w narzędziu producenta lub wiarygodnym czytniku SMART.; Sprawdź obecność radiatora, folię ochronną i kontakt termiczny zgodnie z instrukcją.; Zmierz kopiowanie plików i wydajność przy znanym stanie zapełnienia.; Porównaj zachowanie po schłodzeniu i przy poprawionym przepływie powietrza.; Jeżeli parametry SMART sygnalizują awarię, najpierw zabezpiecz dane, nie wykonuj powtarzanych benchmarków. body: Szybkie SSD NVMe mogą ograniczać wydajność po wzroście temperatury. Odczyty SMART, temperatura kontrolera, przepływ powietrza, radiator i aktualny firmware muszą być oceniane łącznie. warning: Nie usuwaj radiatora ani etykiety SSD bez sprawdzenia warunków gwarancji. Przy błędach nośnika priorytetem jest kopia/obraz danych. source: NVMe specifications and vendor SSD utilities','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','NVMe,PCIe 5,SSD,thermal throttling,SMART','NVMe specifications and vendor SSD utilities'),
('lesson:LATEST-014','lesson','Dyski / SMART i kondycja','NVMe SMART — Critical Warning, Media Errors i Percentage Used','NVMe SMART — Critical Warning, Media Errors i Percentage Used','steps: Zapisz dokładny model i namespace SSD.; Odczytaj SMART/Health log bez uruchamiania długiego benchmarku.; Zanotuj Critical Warning, Available Spare, Percentage Used, temperaturę i liczbę błędów nośnika.; Porównaj wartości z dokumentacją producenta konkretnego modelu.; Przy błędach integralności lub ostrzeżeniu krytycznym zabezpiecz dane i oceń dalsze ryzyko.; Po wymianie SSD zweryfikuj SMART nowego nośnika i test odczytu/zapisu. body: NVMe udostępnia zestaw logów SMART/Health, które zawierają m.in. Critical Warning, temperaturę, Available Spare, Percentage Used oraz Media and Data Integrity Errors. Interpretuj je zgodnie ze specyfikacją i narzędziem producenta. warning: Pojedynczy atrybut SMART nie jest uniwersalną prognozą czasu życia. Nie wykonuj testów zapisu na nośniku z ważnymi, niezabezpieczonymi danymi. source: NVMe SMART health information','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','NVMe,SMART,critical warning,media errors,Percentage Used','NVMe SMART health information'),
('lesson:LATEST-015','lesson','Dyski / kasowanie danych','NVMe Sanitize, Secure Erase i bezpieczne przygotowanie dysku','NVMe Sanitize, Secure Erase i bezpieczne przygotowanie dysku','steps: Potwierdź na piśmie zgodę właściciela na usunięcie danych.; Ustal dokładny numer i model nośnika oraz sprawdź narzędzie producenta.; Zabezpiecz wymagane pliki i potwierdź możliwość odczytu kopii.; Sprawdź, czy nośnik obsługuje wskazaną metodę Sanitize/Secure Erase.; Wykonaj operację zgodnie z procedurą producenta i dokumentuj wynik.; Sprawdź, czy system widzi pusty nośnik oraz czy nie pojawiły się błędy SMART. body: Formatowanie partycji, usuwanie plików, Secure Erase i NVMe Sanitize to różne operacje. Metoda zależy od kontrolera, firmware, szyfrowania i celu serwisowego. Kasowanie jest nieodwracalne z punktu widzenia typowego użytkownika. warning: Nie uruchamiaj Secure Erase, Sanitize, PSID Revert ani Crypto Erase bez świadomej zgody i kopii. Operacja niszczy dostęp do danych. source: NVMe/SSD vendor documentation','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','NVMe,sanitize,secure erase,crypto erase,privacy','NVMe/SSD vendor documentation'),
('lesson:LATEST-016','lesson','Pamięć / DDR5','DDR5 XMP/EXPO — trening pamięci i niestabilny POST','DDR5 XMP/EXPO — trening pamięci i niestabilny POST','steps: Zapisz model modułów, sloty, profil i wersję BIOS.; Przywróć domyślny profil pamięci, jeśli problem pojawił się po OC.; Sprawdź QVL, generację, pojemność i zalecane sloty A2/B2 lub wskazane przez OEM.; Po zmianie pozostaw komputerowi czas na trening pamięci według instrukcji.; Testuj każdy moduł i slot w kontrolowanej konfiguracji.; Włącz profil XMP/EXPO dopiero po stabilnym teście bazowym, następnie sprawdź pamięć i logi. body: Profile XMP i EXPO podnoszą parametry ponad podstawowy profil JEDEC i muszą być wspierane przez CPU, płytę oraz moduły. Trening pamięci po zmianie konfiguracji może trwać dłużej; nie przerywaj go bez sprawdzenia instrukcji płyty. warning: Nie zwiększaj napięć pamięci bez dokumentacji i doświadczenia. Nie zakładaj, że dwa zestawy o podobnym oznaczeniu tworzą wspierany komplet. source: Intel/AMD platform memory compatibility','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','DDR5,XMP,EXPO,memory training,POST','Intel/AMD platform memory compatibility'),
('lesson:LATEST-017','lesson','Pamięć / CUDIMM','CUDIMM — zegar, kompatybilność i diagnostyka DDR5','CUDIMM — zegar, kompatybilność i diagnostyka DDR5','steps: Odczytaj dokładne oznaczenie modułu i dane SPD.; Sprawdź obsługę CUDIMM przez model CPU i płytę.; Zaktualizuj BIOS tylko jeśli producent wskazuje poprawę zgodności pamięci.; Uruchom test na ustawieniach bazowych i jednej konfiguracji modułów.; Oceń stabilność po pełnym treningu pamięci.; W razie błędów wróć do konfiguracji zgodnej z QVL i zgłoś wynik producentowi. body: CUDIMM dodaje sterownik zegara na module pamięci, ale jego funkcjonalność zależy od kontrolera, płyty i BIOS. Wczesne moduły o dużej pojemności lub 4-Rank nie są uniwersalnie obsługiwane. warning: Nie mieszaj bez planu UDIMM, CUDIMM i różnych zestawów. Nie kupuj pamięci wyłącznie po częstotliwości i pojemności. source: Intel Core Ultra 200S Plus memory support','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','CUDIMM,DDR5,clock driver,Intel 800,QVL','Intel Core Ultra 200S Plus memory support'),
('lesson:LATEST-018','lesson','Pamięć / moduły CAMM2','CAMM2 / LPCAMM2 — wymiana pamięci w laptopie','CAMM2 / LPCAMM2 — wymiana pamięci w laptopie','steps: Zidentyfikuj dokładny model laptopa i wariant płyty.; Sprawdź, czy producent opisuje wymienny CAMM2/LPCAMM2 i maksymalną pojemność.; Pobierz instrukcję serwisową, numer części i specyfikację kompatybilności.; Odłącz zasilacz i baterię zgodnie z dokumentacją, zastosuj ESD.; Użyj właściwej kolejności śrub i momentu dokręcania, jeśli OEM go podaje.; Po montażu zweryfikuj ilość pamięci, test stabilności i uśpienie/wybudzenie. body: CAMM2 i LPCAMM2 to formaty modułów pamięci używane w wybranych laptopach. Nie są zamienne z SO-DIMM. Procedura montażu, mocowanie i docisk są specyficzne dla modelu. warning: Nie traktuj CAMM2 jak standardowego SO-DIMM. Nie dociągaj śrub na siłę i nie używaj przypadkowych adapterów. source: JEDEC CAMM2 and OEM service manuals','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','CAMM2,LPCAMM2,laptop,RAM','JEDEC CAMM2 and OEM service manuals'),
('lesson:LATEST-019','lesson','Zasilanie / USB-C PD','USB-C Power Delivery 3.1 — EPR, 140 W i 240 W','USB-C Power Delivery 3.1 — EPR, 140 W i 240 W','steps: Odczytaj wymagane napięcie i moc z etykiety laptopa.; Sprawdź specyfikację portu: czy obsługuje ładowanie i jaki zakres PD.; Użyj certyfikowanego kabla o mocy i funkcjach wymaganych dla zestawu.; Porównaj działanie z oryginalnym zasilaczem OEM.; Obserwuj komunikat ładowania, pobór mocy i temperaturę złącza.; Powtórz test przy obciążeniu i po wznowieniu ze stanu uśpienia. body: USB-C opisuje kształt złącza, a USB Power Delivery negocjuje profile zasilania. EPR może obsługiwać wyższe poziomy mocy, ale wymagane są zgodny host, urządzenie, ładowarka i kabel. warning: Nie podawaj napięcia bezpośrednio na pinach USB-C. Nie stosuj kabli lub adapterów o nieznanych parametrach. source: USB-IF USB Type-C and Power Delivery specifications','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','USB-C,PD 3.1,EPR,240W,charger','USB-IF USB Type-C and Power Delivery specifications'),
('lesson:LATEST-020','lesson','Porty / Thunderbolt 5','Thunderbolt 5 — diagnostyka docka, obrazu i eGPU','Thunderbolt 5 — diagnostyka docka, obrazu i eGPU','steps: Sprawdź, czy port hosta, kabel i dock są certyfikowane dla Thunderbolt 5.; Zidentyfikuj firmware docka i kontrolera oraz wersje sterowników.; Testuj jeden monitor i jedno urządzenie, następnie zwiększaj obciążenie.; Sprawdź rozdzielczość, odświeżanie i układ przepustowości zgodnie z dokumentacją.; Porównaj działanie bezpośrednio z portem hosta.; Zapisz wynik po uśpieniu/wybudzeniu i po odłączeniu docka. body: Thunderbolt 5 deklaruje do 80 Gb/s dwukierunkowo, a w trybie Bandwidth Boost do 120 Gb/s w kierunku obrazu. Parametry zależą od hosta, kabla, urządzenia i trybu pracy. warning: Nie utożsamiaj każdego USB-C z Thunderbolt 5. Nie zakładaj, że kabel do ładowania obsługuje wymaganą przepustowość danych i obrazu. source: Intel Thunderbolt technology overview','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','Thunderbolt 5,80Gbps,120Gbps,dock,eGPU','Intel Thunderbolt technology overview'),
('lesson:LATEST-021','lesson','Porty / USB4','USB4 Version 2.0 — 80 Gb/s i zgodność kabla','USB4 Version 2.0 — 80 Gb/s i zgodność kabla','steps: Sprawdź oznaczenie portu i dane techniczne hosta.; Ustal wersję kontrolera i obsługiwane tryby portu.; Sprawdź certyfikat i parametry kabla.; Testuj transfer z urządzeniem o znanej przepustowości.; W razie problemów porównaj krótki przewód certyfikowany oraz inny port.; Dokumentuj negocjowaną szybkość i zachowanie docka/wyświetlacza. body: USB4 Version 2.0 jest dokumentacją nowej generacji architektury USB. Sama wersja specyfikacji nie oznacza, że konkretny komputer ma port 80 Gb/s; trzeba sprawdzić kontroler, certyfikację i kabel. warning: Nie opisuj portu jako USB4 80 Gb/s na podstawie samego złącza USB-C. Nie stosuj niecertyfikowanych kabli do testów granicznych. source: USB-IF USB4 Specification v2.0','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','USB4 v2,80Gbps,USB-C,cable','USB-IF USB4 Specification v2.0'),
('lesson:LATEST-022','lesson','Sieć / Wi-Fi 7','Wi-Fi 7 — MLO, 320 MHz i diagnostyka połączenia','Wi-Fi 7 — MLO, 320 MHz i diagnostyka połączenia','steps: Sprawdź dokładny adapter i obsługiwane pasma/tryby.; Zapisz wersję sterownika i identyfikator urządzenia.; Zweryfikuj obsługę Wi-Fi 7 po stronie routera oraz ustawienia regionu.; Testuj blisko routera, potem w miejscu typowego użytkowania.; Porównaj jeden link i dostępne pasma; sprawdź interferencje oraz kanał.; Zaktualizuj sterownik od producenta adaptera/OEM i firmware routera. body: Wi-Fi 7 dodaje m.in. Multi-Link Operation, szerokość kanału 320 MHz i 4096-QAM w obsługiwanych konfiguracjach. Rzeczywista wydajność zależy od adaptera, punktu dostępowego, regionu, sterownika, anten i warunków radiowych. warning: Nie obiecuj 5,8 Gb/s lub 320 MHz w każdych warunkach. Wymagane są kompatybilne urządzenia, pasmo, konfiguracja i odpowiedni region. source: Intel Wi-Fi 7 BE200 specifications','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','Wi-Fi 7,MLO,320MHz,4096QAM,BE200','Intel Wi-Fi 7 BE200 specifications'),
('lesson:LATEST-023','lesson','Sieć / adapter Wi-Fi','Wi-Fi 7 — Intel BE200/BE201 i identyfikacja karty M.2','Wi-Fi 7 — Intel BE200/BE201 i identyfikacja karty M.2','steps: Odczytaj dokładny numer adaptera i system ID.; Sprawdź fizyczny format M.2 i dostępne linie interfejsu.; Porównaj listę zatwierdzonych kart w dokumentacji producenta laptopa.; Sprawdź liczbę i typ złączy antenowych oraz ich obsługiwane pasma.; Po wymianie zainstaluj właściwy sterownik Wi-Fi i Bluetooth.; Sprawdź roaming, szybkość, opóźnienia, Bluetooth i wybudzenie. body: Intel Wi-Fi 7 BE200 ma formaty M.2 2230/1216 i interfejsy wskazane przez producenta. Zgodność modułu w laptopie wymaga sprawdzenia anten, slotu, BIOS i listy obsługiwanych części OEM; sam rozmiar M.2 nie wystarcza. warning: Nie instaluj modułu wbrew whitelist lub dokumentacji OEM; nie podłączaj anten na siłę i nie zamieniaj przewodów AUX/MAIN bez oznaczeń. source: Intel Wi-Fi 7 BE200 product specifications','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','Intel BE200,Wi-Fi 7,M.2,PCIe,USB','Intel Wi-Fi 7 BE200 product specifications'),
('lesson:LATEST-024','lesson','Sieć / Ethernet','Ethernet 2.5/5/10 GbE — negocjacja linku i okablowanie','Ethernet 2.5/5/10 GbE — negocjacja linku i okablowanie','steps: Sprawdź prędkość linku na karcie sieciowej i porcie switcha.; Zapisz model adaptera, switcha, routera i sterownika.; Sprawdź kategorię, długość i stan kabla.; Porównaj z krótkim przewodem znanej jakości i innym portem switcha.; Testuj przepustowość lokalnie z serwerem o wyższej przepustowości, nie tylko internetem.; Sprawdź błędy CRC, dropy, negocjację duplex i temperaturę adaptera. body: Wysoka szybkość Ethernet zależy od adaptera, przełącznika, kabla, długości i konfiguracji. Link może negocjować niższą szybkość mimo poprawnego działania interfejsu. warning: Nie diagnozuj sieci LAN wyłącznie testem internetowym; szybkość łącza ISP nie mierzy pełnej wydajności lokalnego Ethernet. source: Intel Ethernet adapter documentation','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','2.5GbE,5GbE,10GbE,Ethernet,cable','Intel Ethernet adapter documentation'),
('lesson:LATEST-025','lesson','Obraz / OLED i Mini-LED','OLED i Mini-LED — diagnostyka obrazu, wypaleń i stref','OLED i Mini-LED — diagnostyka obrazu, wypaleń i stref','steps: Zapisz model matrycy/monitora, firmware i tryb obrazu.; Sprawdź ekran w jednolitych planszach szarości, czerni, bieli i kolorów.; Porównaj obraz przy różnych poziomach jasności i odświeżaniu.; Rozróżnij chwilową retencję od utrwalonego wypalenia po zalecanym czasie obserwacji.; Sprawdź ustawienia HDR, local dimming, pixel shift i odświeżanie panelu według OEM.; Wykonaj test z innym źródłem sygnału i kablem. body: OLED używa pikseli samoemisyjnych, Mini-LED steruje podświetleniem strefowym. Objawy takie jak nierównomierność, retencja, blooming czy martwe piksele mają różne przyczyny i wymagają odrębnego testu. warning: Nie uruchamiaj cykli odświeżania pikseli wielokrotnie bez wskazania producenta; długie testy mogą wpływać na żywotność panelu. source: OEM OLED and Mini-LED service documentation','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','OLED,Mini-LED,burn-in,monitor,HDR','OEM OLED and Mini-LED service documentation'),
('lesson:LATEST-026','lesson','Grafika / laptop hybrid','Advanced Optimus i MUX — diagnostyka grafiki hybrydowej','Advanced Optimus i MUX — diagnostyka grafiki hybrydowej','steps: Zidentyfikuj iGPU, dGPU oraz model laptopa.; Sprawdź, czy model obsługuje MUX/Advanced Optimus.; Zapisz sterowniki obu układów i wersję BIOS.; Testuj ekran wewnętrzny i zewnętrzny przy znanym trybie zasilania.; Porównaj pobór mocy, FPS i przełączanie po podłączeniu zasilacza.; Po aktualizacji sterowników sprawdź uśpienie, wybudzanie i wyjście HDMI/USB-C. body: Laptop z grafiką hybrydową może przełączać tor obrazu między iGPU a dGPU. MUX i Advanced Optimus zależą od firmware, sterowników, trybu zasilania i podłączonego monitora. warning: Nie wymuszaj instalacji sterownika desktopowego w laptopie, jeżeli OEM dostarcza zmodyfikowany pakiet. Nie diagnozuj dGPU tylko po FPS. source: NVIDIA Optimus and OEM laptop graphics documentation','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','MUX,Advanced Optimus,hybrid graphics,GPU','NVIDIA Optimus and OEM laptop graphics documentation'),
('lesson:LATEST-027','lesson','Windows / kamera','Windows 11 26H2 — Multi-App Camera i Basic Camera mode','Windows 11 26H2 — Multi-App Camera i Basic Camera mode','steps: Sprawdź fizyczną przesłonę i skrót klawiaturowy kamery.; Zapisz identyfikator kamery i wersję sterownika.; Sprawdź uprawnienia prywatności dla aplikacji.; Przetestuj kamerę w jednej aplikacji, następnie w dwóch aplikacjach równocześnie.; Sprawdź ustawienia Basic Camera/Group Policy jeśli urządzenie jest zarządzane.; Potwierdź obraz, mikrofon i wybudzanie po uśpieniu. body: Windows 11 26H2 opisuje Multi-App Camera i Basic Camera mode, które mogą wpływać na współdzielenie strumienia kamery oraz stabilność. Problemy trzeba rozdzielić między przesłonę, uprawnienia, sterownik i tryb systemowy. warning: Nie zmieniaj zasad grupy na urządzeniu firmowym bez zgody administratora. Nie instaluj firmware z niezweryfikowanego źródła. source: Windows 11 26H2 features','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','Windows 26H2,camera,multi-app camera,driver','Windows 11 26H2 features'),
('lesson:LATEST-028','lesson','Windows / aktualizacje','Windows Update — safeguard hold i bezpieczne wdrożenie','Windows Update — safeguard hold i bezpieczne wdrożenie','steps: Zapisz wydanie Windows i stan Windows Update.; Sprawdź czy urządzenie jest objęte safeguard hold lub znanym problemem.; Zidentyfikuj niekompatybilny sterownik, aplikację lub firmware.; Sprawdź stronę OEM pod kątem BIOS/sterowników przeznaczonych dla modelu.; Nie wymuszaj aktualizacji za pomocą nieoficjalnych skryptów.; Po usunięciu przyczyny ponownie sprawdź dostępność aktualizacji. body: Safeguard hold może czasowo wstrzymać aktualizację na urządzeniu z powodu zgodności. W serwisie nie należy omijać zabezpieczenia bez potwierdzenia producenta lub Microsoft; diagnoza obejmuje sterowniki, firmware i znane problemy. warning: Nie omijaj safeguard hold przy komputerze klienta, jeśli producent lub Microsoft nie wskazuje bezpiecznej ścieżki. source: Windows 11 release health','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','Windows Update,safeguard hold,26H2,compatibility','Windows 11 release health');
